    this.steps = {};
    for (i = 0; i < R.suffixes.length; i++) this.steps[R.suffixes[i][0]] = R.suffixes[i][1];
    var pre = R.prefixLetters ? "((?:[" + R.prefixLetters + "]{1,2})?)" : "()";
    var spell = [];
    for (i = 0; i < DATA.spell.length; i++) spell.push(DATA.spell[i][0]);
    // groups: 1 prefix, 2 name, 3 dot
    this.book = new RegExp(pre + "(" + (spell.length ? spell.join("|") : "(?!)") + ")(\\.)?(?![" + WCLASS + "])", "g");
